/*
 * Verification harness for spec item 13.1: does mutating a message in
 * a pjsip_module tx callback actually reach the wire, for an initial
 * out-of-dialog request, an in-dialog request generated by the dialog
 * layer, and a response?
 *
 * One pjsua instance calling its own address produces all three:
 * INVITE (initial request), 200 OK (response), BYE (in-dialog).
 *
 * The answer is the packet capture taken around this program, not
 * anything this program prints.
 */
#include "comlink/core.h"

#include <stdatomic.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

static sp_core        *core;
static _Atomic int     confirmed;
static _Atomic int     answered;
static _Atomic uint64_t outbound;

static void on_event(const sp_event *ev, void *user) {
    (void)user;
    switch (ev->type) {
    case SP_EV_INCOMING_CALL:
        printf("EV INCOMING_CALL call=%llu from=%s\n",
               (unsigned long long)ev->u.incoming.call,
               ev->u.incoming.from_uri ? ev->u.incoming.from_uri : "?");
        if (!atomic_exchange(&answered, 1))
            sp_call_answer(core, ev->u.incoming.call, 200, NULL, 0);
        break;
    case SP_EV_CALL_STATE:
        printf("EV CALL_STATE call=%llu state=%d code=%d\n",
               (unsigned long long)ev->u.call_state.call,
               (int)ev->u.call_state.state, ev->u.call_state.last_code);
        if (ev->u.call_state.state == SP_CALL_CONFIRMED)
            atomic_store(&confirmed, 1);
        break;
    case SP_EV_CALL_MEDIA_STATE:
        printf("EV CALL_MEDIA_STATE call=%llu active=%d\n",
               (unsigned long long)ev->u.media.call, ev->u.media.active);
        break;
    default:
        break;
    }
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "usage: %s <config.yaml>\n", argv[0]);
        return 2;
    }
    if (sp_core_create(argv[1], &core) != SP_OK) {
        fprintf(stderr, "create failed\n");
        return 1;
    }
    sp_core_set_event_cb(core, on_event, NULL);
    if (sp_core_start(core) != SP_OK) {
        fprintf(stderr, "start failed: %s\n", sp_last_error_detail(core));
        sp_core_destroy(core);
        return 1;
    }

    sp_call_id call = 0;
    sp_header adhoc[1] = { { .name = "X-Sp-Adhoc", .value = "per-call" } };
    sp_status st = sp_call_make(core, 1, "sip:probe@127.0.0.1:5080",
                                adhoc, 1, &call);
    if (st != SP_OK) {
        fprintf(stderr, "call failed: %s %s\n", sp_strerror(st),
                sp_last_error_detail(core));
        sp_core_stop(core); sp_core_destroy(core);
        return 1;
    }
    atomic_store(&outbound, call);

    for (int i = 0; i < 5000 && !atomic_load(&confirmed); i++)
        usleep(1000);
    printf("confirmed=%d\n", atomic_load(&confirmed));

    /* Let some RTP flow, then hang up so the dialog layer emits BYE. */
    usleep(1500 * 1000);
    sp_call_hangup(core, (sp_call_id)atomic_load(&outbound), 200);
    usleep(1000 * 1000);

    const sp_rule_stat *stats = NULL; size_t n = 0;
    if (sp_rules_stats(core, &stats, &n) == SP_OK)
        for (size_t i = 0; i < n; i++)
            printf("RULE %s hits=%llu\n", stats[i].name,
                   (unsigned long long)stats[i].hits);

    sp_core_stop(core);
    sp_core_destroy(core);
    return 0;
}
